    "v5_jr_naar_contact": "Naar Contact",
    "v5_jr_vragen": "Vragen",
    "v5_jr_vragen_p": "Stuur ons een bericht via de contactpagina.",
    "v5_pv_kort1": "Zonder account weten we niet wie je bent. Sta je statistieken toe, dan telt Google Analytics je bezoek, zonder je naam of e-mailadres.",
    "v5_pv_kort2": "Met een account bewaren we je e-mailadres, je inlogmanier en je leestegoed.",
    "v5_pv_kort3": "Betalen gaat via Stripe; wij zien je kaartgegevens niet.",
    "v5_pv_kort4": "Je account en je gegevens verwijder je zelf in Mijn account.",
    "v5_pv_s1": "Wie we zijn",
    "v5_pv_s1_p": "BrightNews is een website met positief nieuws, te vinden op brightnews.online. Verantwoordelijk voor je gegevens is BrightNews, Vossenstraat 19, 6286 BW Nijswiller (KvK 42048341, btw NL005455019B94).",
    "v5_pv_s2": "Welke gegevens we verwerken",
    "v5_pv_s2_h1": "Zonder account",
    "v5_pv_s2_p1": "We weten niet wie je bent. Je voorkeuren voor taal en weergave bewaart je eigen browser. Sta je in de cookiebalk \"Statistieken\" toe, dan gebruiken we Google Analytics (GA4). Dat telt welke pagina’s worden bekeken, met wat voor apparaat en uit welk land, via een cookie met een willekeurige code. Zonder die toestemming laden we Google Analytics niet.",
    "v5_pv_s2_h2": "Met een gratis account",
    "v5_pv_s2_p2": "Je e-mailadres, je inlogmanier en hoeveel volledige artikelen je deze maand hebt gelezen.",
    "v5_pv_s2_h3": "Met Premium",
    "v5_pv_s2_p3": "Daarnaast je plan en de status van je abonnement. Je betaalgegevens bewaart Stripe, niet wij.",
    "v5_pv_s3": "Waarom we die gegevens gebruiken",
    "v5_pv_s3_p": "Om je te laten inloggen, je leestegoed bij te houden, je abonnement te laten werken en, als je dat wilt, je mails te sturen. [Grondslagen per doel invullen.]",
    "v5_pv_s4": "Met wie we gegevens delen",
    "v5_pv_s4_l1": "Supabase: bewaart je account.",
    "v5_pv_s4_l2": "Stripe: verwerkt je betalingen.",
    "v5_pv_s4_l3": "Google: meet met Google Analytics hoe de site wordt gebruikt, alleen als je \"Statistieken\" toestaat.",
    "v5_pv_s4_l4": "[Mailprovider invullen]: verstuurt onze mails.",
    "v5_pv_s4_p": "We verkopen je gegevens nooit.",
    "v5_pv_s5": "Hoe lang we gegevens bewaren",
    "v5_pv_s5_p": "[Bewaartermijnen invullen.] Verwijder je je account, dan wissen we je gegevens binnen [termijn invullen].",
    "v5_pv_s6": "Cookies",
    "v5_pv_s6_p": "Om in te loggen en je keuzes voor taal en weergave te onthouden gebruiken we de opslag van je browser, niet om je te volgen. Sta je in de cookiebalk \"Statistieken\" toe, dan plaatst Google Analytics (GA4) cookies om bezoeken te tellen. Zonder die toestemming plaatsen we ze niet. Je keuze pas je altijd aan via de cookiebalk.",
    "v5_pv_s6_link": "Cookie-instellingen aanpassen",
    "v5_pv_s7": "Jouw rechten",
    "v5_pv_s7_p": "Je mag je gegevens inzien, laten verbeteren of laten verwijderen. Je account verwijder je zelf in Mijn account. Ben je het niet eens met hoe we met je gegevens omgaan, dan kun je een klacht indienen bij de Autoriteit Persoonsgegevens.",
    "v5_av_kort1": "De samenvattingen zijn gratis. Met een gratis account lees je 5 volledige artikelen per maand.",
    "v5_av_kort2": "Premium begint met 30 dagen gratis en verlengt daarna per maand of per jaar, tot je opzegt in Mijn account.",
    "v5_av_kort3": "AI kiest en vat samen. Dat gaat meestal goed, maar niet altijd; de bron staat er altijd bij.",
    "v5_av_kort4": "Wat je op BrightNews leest, is voor persoonlijk gebruik.",
    "v5_av_s1": "Over deze voorwaarden",
    "v5_av_s1_p": "Deze voorwaarden gelden voor iedereen die brightnews.online gebruikt. BrightNews is van BrightNews, Vossenstraat 19, 6286 BW Nijswiller (KvK 42048341, btw NL005455019B94). Door de site te gebruiken, ga je akkoord met deze voorwaarden.",
    "v5_av_s2": "Wat BrightNews doet",
    "v5_av_s2_p": "BrightNews verzamelt positief nieuws uit betrouwbare bronnen. Claude, een AI-model van Anthropic, kiest de verhalen en schrijft de samenvattingen. Daarbij kan een fout of een gemiste nuance sluipen. Bij elk verhaal staat daarom de bron, zodat je het origineel kunt lezen. BrightNews is niet aansprakelijk voor de gevolgen van informatie in de samenvattingen. [Laten controleren door een jurist.]",
    "v5_av_s3": "Je account",
    "v5_av_s3_p": "Een gratis account is voor één persoon. Daarmee lees je 5 volledige artikelen per maand; het tegoed begint op de eerste van de maand opnieuw. Houd je inloggegevens voor jezelf. Je account verwijder je zelf in Mijn account.",
    "v5_av_s4": "Premium en betalen",
    "v5_av_s4_l1": "Proefperiode: Premium begint met 30 dagen gratis. Zeg je in die tijd op, dan betaal je niets.",
    "v5_av_s4_l2": "Prijs: €2,95 per maand of €24,95 per jaar. Je betaalt vooraf voor de gekozen periode, via Stripe.",
    "v5_av_s4_l3": "Verlengen: je abonnement verlengt vanzelf per maand of per jaar, tot je opzegt. Betaalbewijzen krijg je van Stripe.",
    "v5_av_s4_l4": "Opzeggen: dat doe je zelf, op elk moment, in Mijn account. Je houdt Premium tot het einde van de periode waarvoor je al betaald hebt.",
    "v5_av_s4_p": "Hoe en wanneer je je geld terugkrijgt, staat in het refundbeleid.",
    "v5_av_s5": "Gebruik van de inhoud",
    "v5_av_s5_p": "Wat je op BrightNews leest, is voor persoonlijk gebruik. Delen via de knoppen bij een verhaal mag altijd. Artikelen of data commercieel verspreiden mag alleen met onze schriftelijke toestemming. De oorspronkelijke artikelen blijven van hun bron.",
    "v5_av_s6": "Wijzigingen",
    "v5_av_s6_p": "We kunnen deze voorwaarden aanpassen. De nieuwste versie staat altijd op deze pagina, met de datum bovenaan. Veranderen ze iets wezenlijks voor Premium, dan laten we het je eerst weten. [Termijn invullen.]",
    "v5_rf_kort1": "De eerste 30 dagen zijn gratis. Zeg je in die tijd op, dan betaal je niets.",
    "v5_rf_kort2": "Binnen 14 dagen na je eerste betaling krijg je op verzoek je geld volledig terug.",
    "v5_rf_kort3": "Daarna kun je altijd opzeggen; je houdt Premium tot het einde van de periode, zonder terugbetaling over de rest.",
    "v5_rf_s1": "De proefperiode",
    "v5_rf_s1_p": "Premium begint met 30 dagen gratis. Vandaag betaal je €0. Zeg je binnen die 30 dagen op in Mijn account, dan volgt er geen betaling.",
    "v5_rf_s2": "14 dagen geld terug",
    "v5_rf_s2_p": "Binnen 14 dagen na je eerste betaling voor Glow of Shine krijg je op verzoek een volledige terugbetaling, hoeveel artikelen je ook al hebt gelezen.",
    "v5_rf_s3": "Verhouding tot je herroepingsrecht",
    "v5_rf_s3_p": "Bij het afrekenen vraag je om meteen toegang tot Premium. Daarmee doe je afstand van het wettelijke herroepingsrecht van 14 dagen voor digitale diensten. Wettelijk zijn we dus niet verplicht terug te betalen; de 14 dagen geld terug geven we je toch, uit eigen beweging. [Laten controleren door een jurist.]",
    "v5_rf_s4": "Zo vraag je het aan",
    "v5_rf_s4_p": "Stuur een bericht via Contact en kies \"Vraag over mijn abonnement\". Noem het e-mailadres van je account en de datum van betaling. We betalen binnen een paar werkdagen terug via Stripe, op dezelfde manier als je betaalde.",
    "v5_rf_s5": "Na de eerste 14 dagen",
    "v5_rf_s5_p": "Daarna kun je op elk moment opzeggen in Mijn account. Je houdt Premium tot het einde van de periode waarvoor je al betaald hebt; over die resterende periode betalen we niet terug.",
