    "v5_bd_titel_bezig": "Bedankt voor je aanmelding",
    "v5_bd_lead_bezig": "Je proefperiode is gestart: vandaag betaal je €0. De eerste betaling, {bedrag}, is op {datum}. We zetten Premium nu aan voor {email}. Dat duurt meestal een paar seconden.",
    "v5_bd_niets_doen": "Je hoeft niets te doen",
    "v5_bd_niets_doen_tekst": "Deze pagina ververst vanzelf zodra Premium klaarstaat. Je kunt hem ook gewoon sluiten: je Premium staat daarna in Mijn account.",
    "v5_bd_lead_traag": "Je aanmelding is gelukt, maar Premium staat nog niet aan. Dat duurt langer dan normaal.",
    "v5_bd_traag_titel": "Meld je niet opnieuw aan",
    "v5_bd_traag_tekst": "Ververs de pagina over een minuut. Lukt het dan nog niet, laat het ons weten. Je betaalt niets dubbel: je proefperiode van 30 dagen gaat pas in als Premium aanstaat, en de eerste betaling volgt pas daarna.",
    "v5_bd_verversen": "Pagina verversen",
    "v5_bd_status_klaar": "Premium staat aan.",
    "v5_bd_status_traag": "Premium staat nog niet aan. Dat duurt langer dan normaal.",
    "v5_oo_h1": "Goed nieuws, zonder ruis",
    "v5_oo_lead": "BrightNews verzamelt elke dag nieuws over wat er goed gaat in de wereld. Uit betrouwbare bronnen, kort samengevat, in vijf talen.",
    "v5_oo_waarom_h2": "Waarom BrightNews",
    "v5_oo_waarom_p1": "Het meeste nieuws gaat over wat misgaat. Dat is belangrijk, maar het is niet het hele verhaal. Elke dag lost iemand ook een probleem op: een nieuwe behandeling, een schonere rivier, een uitvinding die energie bespaart.",
    "v5_oo_waarom_p2": "BrightNews laat die kant zien. Niet om de problemen weg te praten, maar zodat je na het lezen weet wat er wél vooruitgaat.",
    "v5_oo_werkt_h2": "Zo werkt het",
    "v5_oo_werkt_intro": "BrightNews heeft geen redactie. Drie stappen, elke dag opnieuw.",
    "v5_oo_stap1_t": "1. Verzamelen",
    "v5_oo_stap1_p": "We halen nieuws op uit betrouwbare bronnen, in vijf talen.",
    "v5_oo_stap2_t": "2. Kiezen",
    "v5_oo_stap2_p": "AI geeft elk bericht een score. Alleen nieuws dat echt iets oplevert, komt op de site.",
    "v5_oo_stap3_t": "3. Samenvatten",
    "v5_oo_stap3_p": "Elk verhaal krijgt een korte samenvatting, met een link naar de oorspronkelijke bron.",
    "v5_oo_ai_h2": "Eerlijk over AI",
    "v5_oo_ai_p1": "Kiezen en samenvatten doet Claude, een AI-model van Anthropic. Dat gaat meestal goed, maar niet altijd. Daarom staat bij elk verhaal de bron, zodat je het origineel kunt lezen.",
    "v5_oo_ai_fout": "Zie je een fout in een samenvatting? {link}.",
    "v5_oo_ai_link": "Laat het ons weten",
    "v5_oo_talen_h2": "Zes onderwerpen, vijf talen",
    "v5_oo_talen_intro": "Nederlands, English, Deutsch, Français en Español. Kies je taal via Instellingen bovenaan de pagina.",
    "v5_oo_onderwerpen": "Onderwerpen",
    "v5_oo_betaald_h2": "Hoe BrightNews wordt betaald",
    "v5_oo_betaald_p1": "Alle samenvattingen zijn gratis, voor iedereen. Met een gratis account lees je 5 volledige artikelen per maand. Premium kost €2,95 per maand en betaalt de servers en de AI. Zo blijft BrightNews onafhankelijk.",
    "v5_oo_vragen_h2": "Vragen of ideeën?",
    "v5_oo_vragen_intro": "We lezen alles wat je stuurt.",
    "v5_zk_h1": "Hoe een bericht op BrightNews komt",
    "v5_zk_lead": "BrightNews heeft geen redactie. Een vaste werkwijze bepaalt wat je ziet. Hier staat die werkwijze, stap voor stap.",
    "v5_zk_bron_h2": "Van bron tot samenvatting",
    "v5_zk_stap1_t": "Ophalen",
    "v5_zk_stap1_p": "Een automatisch programma haalt elke dag nieuwe berichten op uit betrouwbare nieuwsbronnen.",
    "v5_zk_stap2_t": "Beoordelen",
    "v5_zk_stap2_p": "Claude, een AI-model van Anthropic, leest elk bericht en geeft punten op drie criteria: goed gevoel (0 tot 3), positieve formulering (0 tot 3) en relevantie (0 tot 4). Samen is dat een score van 0 tot 10.",
    "v5_zk_stap3_t": "Kiezen",
    "v5_zk_stap3_p": "Op de site komt alleen een bericht met een score van 8 of hoger, en met minstens 2 punten op elk criterium. Op een rustige dag zijn dat er minder; we vullen niet aan met minder goed nieuws.",
    "v5_zk_stap4_t": "Samenvatten en indelen",
    "v5_zk_stap4_p": "Claude schrijft een korte samenvatting in vijf talen en kiest één van de zes onderwerpen: Tech, Gezondheid, Wetenschap, Lifestyle, Milieu of Financiën.",
    "v5_zk_stap5_t": "Foto controleren",
    "v5_zk_stap5_p": "Is de foto kleiner dan 800 pixels breed, een logo of een effen vlak? Dan tonen we geen foto, maar ons eigen beeld.",
    "v5_zk_stap6_t": "Dagoverzicht maken",
    "v5_zk_stap6_p": "Eén keer per dag bundelen we de belangrijkste verhalen in een dagoverzicht, met alle bronnen erbij. Een dag loopt van 00:00 tot 24:00 Nederlandse tijd.",
    "v5_zk_letten_h2": "Waar we op letten",
    "v5_zk_letten_intro": "Goed nieuws betekent niet: alleen leuke berichten. Elk bericht krijgt punten op drie criteria, samen 0 tot 10. Vanaf 8 komt het op de site, als elk criterium minstens 2 haalt.",
    "v5_zk_punten_h3": "Zo geven we punten",
    "v5_zk_punt1": "Goed gevoel, 0 tot 3: word je blij, hoopvol of warm van de kern van het verhaal?",
    "v5_zk_punt2": "Positieve formulering, 0 tot 3: vertelt het bericht zelf wat er goed gaat, zonder crisistaal?",
    "v5_zk_punt3": "Relevantie, 0 tot 4: betekent het iets voor de samenleving, of herken je er jezelf of je buurt in?",
    "v5_zk_liggen_h3": "Dit laten we liggen",
    "v5_zk_liggen1": "Oorlog, geweld, misdaad of rampen als kern van het verhaal",
    "v5_zk_liggen2": "Reclame, productnieuws, reviews en beursnieuws",
    "v5_zk_liggen3": "Politiek, roddels, lijstjes en clickbait",
    "v5_zk_elk_h2": "Wat je bij elk verhaal ziet",
    "v5_zk_elk_intro": "Zo kun je zelf nagaan waar het vandaan komt.",
    "v5_zk_elk1": "De bron, met een link naar het oorspronkelijke artikel",
    "v5_zk_elk2": "Het onderwerp",
    "v5_zk_elk3": "Wanneer we het verhaal hebben verwerkt, in jouw tijdzone",
    "v5_zk_elk4": "Een samenvatting; met Premium of tegoed ook het volledige artikel",
    "v5_zk_grenzen_h2": "Wat AI niet altijd goed doet",
    "v5_zk_grenzen_p1": "AI kan een nuance missen of een getal verkeerd overnemen. Niemand leest elk verhaal vooraf. Daarom staat de bron er altijd bij, en kun je een fout melden. Meldingen lezen we wel, en een fout passen we aan.",
    "v5_zk_fout": "Fout gezien? {link}.",
    "v5_zk_meld": "Meld het via Feedback",
    "v5_zk_vragen": "Vragen",
    "v5_zk_faq1_v": "Waarom zie ik soms maar een paar verhalen?",
    "v5_zk_faq1_a": "Op rustige dagen halen minder berichten een hoge score. We vullen dan niet aan met minder goed nieuws.",
    "v5_zk_faq2_v": "Kan ik een verhaal of bron voorstellen?",
    "v5_zk_faq2_a": "Ja, stuur het via Contact. Een voorgesteld verhaal gaat door dezelfde beoordeling als elk ander bericht, dus we kunnen niet beloven dat het op de site komt.",
    "v5_zk_faq3_v": "Betaalt iemand om op BrightNews te komen?",
