    "privacy_list_subscription": "<strong>Abonnementen:</strong> Voor 'Glow' en 'Shine' leden verwerken we betalingen via Stripe, onze Merchant of Record. Wij slaan zelf geen creditcardnummers op op onze servers.",
    "privacy_list_account": "<strong>Accountgegevens:</strong> Voor inloggen en accountbeheer gebruiken we Supabase (gehost binnen de EU) als verwerker van je e-mailadres en accountinstellingen.",
    "privacy_list_hosting": "<strong>Gegevensopslag:</strong> Je accountgegevens en premium-artikelen worden opgeslagen bij Supabase, op servers binnen de EU en onder een verwerkersovereenkomst (DPA). De website zelf wordt gehost via GitHub Pages.",
    "privacy_list_newsletter": "<strong>Aanmelding nieuwsbrief:</strong> Als je je aanmeldt voor updates via onze launchpagina, wordt je e-mailadres uitsluitend voor die aanmelding verwerkt door Formspree.",
    "cookies_title": "Cookies & Technologie",
    "cookies_text": "BrightNews gebruikt functionele cookies en lokale opslag om je taalvoorkeuren en inlogsessie te onthouden. We gebruiken minimale, privacyvriendelijke analyses. Voor tracking buiten de functionele noodzaak vragen we altijd eerst toestemming.",
    "transparency_title": "AI & Toegankelijkheid",
    "transparency_text": "Ons nieuws wordt gegenereerd door AI. Wij geloven in transparantie: elk artikel bevat een AI-disclaimer. Bovendien zetten wij ons in voor de <strong>WCAG 2.1 AA</strong> standaarden voor een toegankelijke ervaring.",
    "feat_14days": "✅ Directe toegang",
    "feat_money": "✅ Geen verborgen kosten",
    "withdrawal_consent_label": "Ik ga akkoord dat de dienst direct start en doe daarmee afstand van mijn wettelijke herroepingsrecht van 14 dagen.",
    "withdrawal_consent_required": "Vink eerst het vakje aan om verder te gaan.",
    "portal_url_missing": "Kon geen beheerlink vinden. Neem contact op via de contactpagina om je abonnement stop te zetten.",
    "privacy_list_withdrawal": "<strong>Herroepingsrecht:</strong> Bij het starten van een abonnement stem je in met directe levering en doe je afstand van de wettelijke bedenktijd.",
    "colofon_val_odr": "EU ODR Platform",
    "privacy_list_payments": "<strong>Betalingen:</strong> Transacties worden veilig verwerkt via Stripe, onze Merchant of Record. Wij bewaren zelf geen creditcardgegevens.",
    "cookies_text2": "BrightNews gebruikt functionele cookies en lokale opslag om je voorkeuren, zoals je taal en inlogsessie, veilig te onthouden. Voor analytische of tracking cookies vragen we altijd vooraf toestemming via de banner. Zo heb jij volledige controle over je eigen data.",
