    "about_badge": "Hallo zonneschijn! ☀️",
    "about_hero_title": "Wij zijn jouw dagelijkse dosis goed nieuws.",
    "about_hero_p": "Eerlijk is eerlijk: de wereld kan soms best een beetje overweldigend zijn. Bij BrightNews zetten we de zonnebril op en focussen we ons op de mooie dingen die wél gebeuren.",
    "about_why_title": "Waarom BrightNews?",
    "about_why_p": "Omdat we geloven dat een positieve blik besmettelijk is! Van wetenschappers die oceanen schoonmaken tot kleine daden van vriendelijkheid op de hoek van de straat; er is zoveel om vrolijk van te worden. Wij filteren de ruis weg en laten de lichtpuntjes zien.",
    "about_feat1_title": "Geen Wolken",
    "about_feat1_p": "Alleen berichten waar je energie van krijgt en die je met een gerust hart kunt delen.",
    "about_feat2_title": "Wereldwijd",
    "about_feat2_p": "Goede dingen gebeuren overal, van Amsterdam tot aan de andere kant van de oceaan.",
    "about_feat3_title": "Stipt om 12:00",
    "about_feat3_p": "Precies op tijd voor de lunch serveren wij je dagelijkse dosis goed nieuws. Elke dag vers om 12:00 en 00:00 UTC (12 PM en 12 AM).",
    "about_how_title": "Hoe toveren we dit op je scherm?",
    "about_how_p": "Geen ingewikkelde handleidingen, maar een slimme computer (onze AI) die dol is op blije verhalen. Dit is wat er elke dag gebeurt:",
    "about_step1": "<strong>Stap 1: Speuren 🔍</strong> - Onze computer leest duizenden kranten en blogs over de hele wereld.",
    "about_step2": "<strong>Stap 2: Glimlach-check 😊</strong> - Is het bericht hoopvol? Worden we er blij van? Zo ja, dan mag het door!",
    "about_step3": "<strong>Stap 3: Vertalen 🗣️</strong> - We maken er een leuk kort verhaal van in jouw eigen taal.",
    "about_step4": "<strong>Stap 4: Tadaa! 🎉</strong> - Om 12:00 uur precies staat het voor je klaar op de website.",
    "climate_title": "Samen met Stripe halen we CO₂ uit de lucht",
    "climate_text": "Een vast deel van elk abonnement gaat via Stripe Climate naar het permanent uit de lucht halen van CO₂. Stripe bundelt die bijdragen en koopt er koolstofverwijdering mee in bij bedrijven die die technologie nu aan het opbouwen zijn — werk dat vandaag nog te duur is om vanzelf van de grond te komen. Zo lees je bij ons niet alleen goed klimaatnieuws, je maakt er ook een klein stukje van mogelijk.",
    "climate_link": "Lees hoe Stripe Climate werkt",
    "editorial_independence_title": "Redactionele Onafhankelijkheid",
    "editorial_independence_text": "Onze AI-samenvattingen komen volledig redactioneel onafhankelijk van de bronmedia tot stand. Geen enkele nieuwsbron waarvan wij content samenvatten, betaalt ons of heeft invloed op welke verhalen we selecteren of hoe we ze herschrijven. We linken bij elk artikel naar het origineel, zodat je zelf kunt controleren en verder kunt lezen.",
    "pricing_title": "Kies jouw dosis zonneschijn ☀️",
