    "terms_title": "Onze Afspraken ✨",
    "terms_subtitle": "Helderheid en positiviteit in alles wat we doen.",
    "terms_sec1_title": "1. Onze Missie",
    "terms_sec1_text": "BrightNews brengt uitsluitend positief nieuws. Onze AI-engine scant wereldwijd bronnen om jou meerdere keren per dag te voorzien van een verse dosis optimisme. Door gebruik te maken van onze site, ga je akkoord met deze voorwaarden.",
    "terms_sec2_title": "2. Gebruik van de Content",
    "terms_sec2_text": "Alles wat je op BrightNews leest, is bedoeld voor persoonlijk gebruik. Het is niet toegestaan om onze artikelen of data commercieel te verspreiden zonder schriftelijke toestemming van Maarten de Klerk.",
    "terms_sec3_title": "3. Abonnementen (Premium)",
    "terms_sec3_list1": "<strong>Toegang:</strong> Premium artikelen zijn exclusief voor leden met een actief abonnement.",
    "terms_sec3_list2": "<strong>Betaling:</strong> Je betaalt vooraf voor de gekozen periode.",
    "terms_sec3_list4": "<strong>Automatische verlenging:</strong> Je abonnement verlengt automatisch per gekozen periode (maand of jaar), ook na een gratis proefperiode, totdat je opzegt. Je ontvangt de aankoopbevestiging en facturen van Stripe.",
    "terms_sec3_list3": "<strong>Opzeggen:</strong> Je kunt je abonnement op elk moment stopzetten via je profielpagina. De toegang blijft behouden tot de einddatum van de factuurperiode.",
    "terms_sec4_title": "4. De 'Bright' AI-Garantie",
    "terms_sec4_text": "Onze AI doet zijn best om alleen de meest positieve verhalen te selecteren. Hoewel we streven naar 100% nauwkeurigheid en positiviteit, is de content gegenereerd door AI en kan deze soms een interpretatiefout bevatten. BrightNews is niet aansprakelijk voor de gevolgen van informatie in de artikelen.",
    "terms_sec5_title": "5. Wijzigingen",
    "terms_sec5_text": "De wereld verandert, en BrightNews ook. We kunnen deze voorwaarden af en toe aanpassen om ze nog helderder te maken. De nieuwste versie staat altijd hier.",
    "refunds_title": "Terugbetalingen ✨",
    "refunds_subtitle": "Niet tevreden? Je krijgt je geld terug.",
    "refunds_sec1_title": "1. 14 dagen niet-goed-geld-terug",
    "refunds_sec1_text": "Binnen 14 dagen na je aankoop van een Glow- of Shine-abonnement kun je op verzoek een volledige terugbetaling krijgen — ongeacht hoeveel artikelen je al hebt gelezen. Dit is een vrijwillige garantie van BrightNews, geen wettelijk verplicht recht (zie punt 2 hieronder).",
    "refunds_sec2_title": "2. Verhouding tot je herroepingsrecht",
    "refunds_sec2_text": "Omdat je bij het afsluiten van een abonnement direct toegang krijgt tot premium content, vraag je bij het afrekenen expliciet om onmiddellijke levering en doe je daarmee afstand van het wettelijke herroepingsrecht van 14 dagen dat normaal voor digitale diensten geldt. Dat betekent dat we wettelijk niet verplicht zijn om terug te betalen. We bieden deze garantie toch aan, uit coulance — je betaalt pas echt als je tevreden bent.",
    "refunds_sec3_title": "3. Hoe vraag je een terugbetaling aan?",
    "refunds_sec3_text": "Stuur een e-mail naar info@brightnews.online met het e-mailadres van je account en de datum van aankoop. We verwerken je verzoek binnen enkele werkdagen en betalen terug via Stripe, op dezelfde manier als je oorspronkelijke betaling.",
    "refunds_sec4_title": "4. Na de eerste 14 dagen",
    "refunds_sec4_text": "Na deze periode kun je je abonnement op elk moment stopzetten via je profielpagina. Je toegang blijft dan actief tot het einde van de lopende factuurperiode, maar er volgt geen terugbetaling voor die resterende periode. Zie onze Algemene Voorwaarden voor de volledige opzegvoorwaarden.",
    "colofon_title": "Wie zijn wij? (Colofon)",
