    "v5_bd_titel_gelukt": "Welcome to Premium",
    "v5_bd_lead_gelukt": "Your trial has started and runs until {datum}. You pay nothing until then.",
    "v5_bd_abonnement": "Your subscription",
    "v5_bd_plan": "Plan",
    "v5_bd_per_jaar": "per year",
    "v5_bd_per_maand": "per month",
    "v5_bd_bedrag_jaar": "€24.95",
    "v5_bd_bedrag_maand": "€2.95",
    "v5_bd_eerste_betaling": "First payment",
    "v5_bd_bedrag_op": "{bedrag} on {datum}",
