    "v5_bd_gestuurd_naar": "Sent to {email}",
    "v5_bd_lees_vandaag": "Read today's news",
    "v5_bd_verder_lezen": "Continue reading",
    "v5_bd_account_regel": "You can cancel or change your plan in {account}.",
    "v5_bd_titel_bezig": "Thanks for signing up",
    "v5_bd_lead_bezig": "Your trial has started: today you pay €0. The first payment, {bedrag}, is on {datum}. We're now switching on Premium for {email}. That usually takes a few seconds.",
    "v5_bd_niets_doen": "You don't need to do anything",
    "v5_bd_niets_doen_tekst": "This page refreshes by itself as soon as Premium is ready. You can also just close it: your Premium will then be in My account.",
    "v5_bd_lead_traag": "Your sign-up worked, but Premium isn't on yet. It's taking longer than usual.",
    "v5_bd_traag_titel": "Don't sign up again",
    "v5_bd_traag_tekst": "Refresh the page in a minute. If it still doesn't work, let us know. You won't pay twice: your 30-day trial only starts once Premium is on, and the first payment only comes after that.",
    "v5_bd_verversen": "Refresh page",
    "v5_bd_status_klaar": "Premium is on.",
    "v5_bd_status_traag": "Premium isn't on yet. It's taking longer than usual.",
    "v5_oo_h1": "Good news, without the noise",
    "v5_oo_lead": "Every day, BrightNews collects news about what's going well in the world. From reliable sources, briefly summarised, in five languages.",
    "v5_oo_waarom_h2": "Why BrightNews",
    "v5_oo_waarom_p1": "Most news is about what goes wrong. That matters, but it isn't the whole story. Every day someone also solves a problem: a new treatment, a cleaner river, an invention that saves energy.",
    "v5_oo_waarom_p2": "BrightNews shows that side. Not to talk the problems away, but so that after reading you know what is moving forward.",
    "v5_oo_werkt_h2": "How it works",
    "v5_oo_werkt_intro": "BrightNews has no editorial team. Three steps, every day again.",
    "v5_oo_stap1_t": "1. Collect",
    "v5_oo_stap1_p": "We gather news from reliable sources, in five languages.",
    "v5_oo_stap2_t": "2. Choose",
    "v5_oo_stap2_p": "AI gives every story a score. Only news that truly adds something makes it onto the site.",
    "v5_oo_stap3_t": "3. Summarise",
    "v5_oo_stap3_p": "Every story gets a short summary, with a link to the original source.",
    "v5_oo_ai_h2": "Honest about AI",
    "v5_oo_ai_p1": "Choosing and summarising is done by Claude, an AI model from Anthropic. That usually goes well, but not always. That's why every story shows its source, so you can read the original.",
    "v5_oo_ai_fout": "Spot a mistake in a summary? {link}.",
    "v5_oo_ai_link": "Let us know",
    "v5_oo_talen_h2": "Six topics, five languages",
    "v5_oo_talen_intro": "Nederlands, English, Deutsch, Français and Español. Choose your language under Settings at the top of the page.",
    "v5_oo_onderwerpen": "Topics",
    "v5_oo_betaald_h2": "How BrightNews is paid for",
    "v5_oo_betaald_p1": "All summaries are free, for everyone. With a free account you can read 5 full articles a month. Premium costs €2.95 a month and pays for the servers and the AI. That keeps BrightNews independent.",
    "v5_oo_vragen_h2": "Questions or ideas?",
    "v5_oo_vragen_intro": "We read everything you send.",
    "v5_zk_h1": "How a story gets onto BrightNews",
    "v5_zk_lead": "BrightNews has no editorial team. A fixed method decides what you see. Here is that method, step by step.",
    "v5_zk_bron_h2": "From source to summary",
    "v5_zk_stap1_t": "Fetch",
    "v5_zk_stap1_p": "An automated program fetches new stories every day from reliable news sources.",
    "v5_zk_stap2_t": "Score",
    "v5_zk_stap2_p": "Claude, an AI model from Anthropic, reads every story and awards points on three criteria: good feeling (0 to 3), positive framing (0 to 3) and relevance (0 to 4). Together that makes a score from 0 to 10.",
    "v5_zk_stap3_t": "Choose",
    "v5_zk_stap3_p": "Only a story with a score of 8 or higher, and at least 2 points on every criterion, makes it onto the site. On a quiet day there are fewer; we don't fill up with less good news.",
    "v5_zk_stap4_t": "Summarise and categorise",
    "v5_zk_stap4_p": "Claude writes a short summary in five languages and picks one of the six topics: Tech, Health, Science, Lifestyle, Environment or Finance.",
    "v5_zk_stap5_t": "Check the photo",
    "v5_zk_stap5_p": "Is the photo narrower than 800 pixels, a logo or a plain block of colour? Then we show our own image instead.",
    "v5_zk_stap6_t": "Make the daily overview",
    "v5_zk_stap6_p": "Once a day we bundle the most important stories into a daily overview, with all sources included. A day runs from 00:00 to 24:00 Dutch time.",
    "v5_zk_letten_h2": "What we look for",
    "v5_zk_letten_intro": "Good news doesn't mean: only nice stories. Every story gets points on three criteria, 0 to 10 in total. From 8 up it goes on the site, if every criterion scores at least 2.",
    "v5_zk_punten_h3": "How we award points",
    "v5_zk_punt1": "Good feeling, 0 to 3: does the core of the story make you happy, hopeful or warm?",
    "v5_zk_punt2": "Positive framing, 0 to 3: does the story itself say what is going well, without crisis language?",
    "v5_zk_punt3": "Relevance, 0 to 4: does it mean something for society, or do you recognise yourself or your neighbourhood in it?",
    "v5_zk_liggen_h3": "What we leave out",
    "v5_zk_liggen1": "War, violence, crime or disasters at the core of the story",
    "v5_zk_liggen2": "Advertising, product news, reviews and stock market news",
    "v5_zk_liggen3": "Politics, gossip, listicles and clickbait",
    "v5_zk_elk_h2": "What you see with every story",
    "v5_zk_elk_intro": "So you can check for yourself where it comes from.",
    "v5_zk_elk1": "The source, with a link to the original article",
    "v5_zk_elk2": "The topic",
    "v5_zk_elk3": "When we processed the story, in your time zone",
    "v5_zk_elk4": "A summary; with Premium or credit also the full article",
    "v5_zk_grenzen_h2": "What AI doesn't always get right",
    "v5_zk_grenzen_p1": "AI can miss a nuance or copy a number wrongly. Nobody reads every story beforehand. That's why the source is always included, and you can report a mistake. We do read reports, and we correct mistakes.",
    "v5_zk_fout": "Spotted a mistake? {link}.",
    "v5_zk_meld": "Report it via Feedback",
    "v5_zk_vragen": "Questions",
    "v5_zk_faq1_v": "Why do I sometimes see only a few stories?",
    "v5_zk_faq1_a": "On quiet days fewer stories reach a high score. We don't fill up with less good news.",
    "v5_zk_faq2_v": "Can I suggest a story or source?",
    "v5_zk_faq2_a": "Yes, send it via Contact. A suggested story goes through the same scoring as every other story, so we can't promise it will appear on the site.",
    "v5_zk_faq3_v": "Does anyone pay to appear on BrightNews?",
    "v5_zk_faq3_a": "No. There is no advertising on BrightNews and nobody can pay for a spot. The scoring is the same for every story.",
    "v5_ct_lead": "A question, an idea or something that isn't right? Send us a message. We read everything.",
    "v5_ct_stuur_h2": "Send a message",
    "v5_ct_naam": "Name",
