    "colofon_link_odr": "EU ODR Platform",
    "privacy_text_intro": "At BrightNews, we focus on positivity. That applies to your data too. We only process what is strictly necessary to provide our service.",
    "privacy_list_subscription": "<strong>Subscriptions:</strong> For 'Glow' and 'Shine' members, we process payments via Stripe, our Merchant of Record. We do not store credit card numbers on our own servers.",
    "privacy_list_account": "<strong>Account Data:</strong> We use Supabase (hosted in the EU) to process your email address and account settings for login and account management.",
    "privacy_list_hosting": "<strong>Data storage:</strong> Your account data and premium articles are stored with Supabase, on servers within the EU and under a Data Processing Agreement (DPA). The website itself is hosted via GitHub Pages.",
    "privacy_list_newsletter": "<strong>Newsletter Signup:</strong> If you sign up for updates via our launch page, your email address is processed by Formspree solely to receive your signup.",
    "cookies_title": "Cookies & Technology",
    "cookies_text": "BrightNews uses functional cookies and local storage to remember your language preferences and login session. We use minimal, privacy-friendly analytics to improve the site. For any tracking beyond functional necessity, we will always ask your permission first.",
    "transparency_title": "AI & Accessibility",
    "transparency_text": "Our news is generated by AI. We believe in transparency: every article includes an AI-disclaimer. Furthermore, we are committed to the <strong>WCAG 2.1 AA</strong> standards to ensure accessibility for everyone.",
    "renewal_notice": "After the free trial € 2.95/month; renews automatically, cancel anytime.",
    "renewal_notice_year": "After the free trial € 24.95/year; renews automatically, cancel anytime.",
    "feat_14days": "✅ Immediate access",
    "feat_money": "✅ No hidden fees",
    "withdrawal_consent_label": "I agree that the service starts immediately and that I therefore waive my statutory 14-day right of withdrawal.",
    "withdrawal_consent_required": "Please check the box first to continue.",
    "portal_url_missing": "Could not find a management link. Please contact us via the contact page to cancel your subscription.",
    "privacy_list_withdrawal": "<strong>Right of Withdrawal:</strong> By starting a subscription, you agree to immediate delivery and waive your statutory cooling-off period.",
    "colofon_val_odr": "EU ODR Platform",
    "privacy_list_payments": "<strong>Payments:</strong> Transactions are securely processed via Stripe, our Merchant of Record. We do not store credit card data.",
    "cookies_text2": "BrightNews uses functional cookies and local storage to securely remember your preferences, such as your language and login session. For analytical or tracking cookies, we always ask for your consent via the banner first. This way, you stay in full control of your own data.",
