    "about_badge": "Hello sunshine! ☀️",
    "about_hero_title": "We are your daily dose of good news.",
    "about_hero_p": "Let's be honest: the world can be a bit overwhelming sometimes. At BrightNews, we put on our sunglasses and focus on the beautiful things that ARE happening.",
    "about_why_title": "Why BrightNews?",
    "about_why_p": "Because we believe a positive outlook is contagious! From scientists cleaning oceans to small acts of kindness; there is so much to be happy about. We filter out the noise and show the highlights.",
    "about_feat1_title": "No Clouds",
    "about_feat1_p": "Only stories that give you energy and that you can share with confidence.",
    "about_feat2_title": "Worldwide",
    "about_feat2_p": "Good things happen everywhere, from Amsterdam to the other side of the ocean.",
    "about_feat3_title": "Sharp at 12:00",
    "about_feat3_p": "Right on time for lunch, we serve your daily dose of good news. Fresh every day at 12:00 and 00:00 UTC (12 PM and 12 AM).",
    "about_how_title": "How do we bring this to your screen?",
    "about_how_p": "No complicated manuals, just a smart computer (our AI) that loves happy stories. This is what happens every day:",
    "about_step1": "<strong>Step 1: Searching 🔍</strong> - Our computer reads thousands of newspapers and blogs worldwide.",
    "about_step2": "<strong>Step 2: Smile-check 😊</strong> - Is the message hopeful? Does it make us happy? If so, it passes!",
    "about_step3": "<strong>Step 3: Translating 🗣️</strong> - We turn it into a fun short story in your own language.",
    "about_step4": "<strong>Step 4: Tadaa! 🎉</strong> - At exactly 12:00 PM, it's ready for you on the website.",
    "climate_title": "Together with Stripe we take CO₂ out of the air",
    "climate_text": "A fixed share of every subscription goes through Stripe Climate towards permanently removing CO₂ from the atmosphere. Stripe pools those contributions and buys carbon removal from companies still building that technology — work that is far too expensive today to get off the ground on its own. So with us you do not just read good climate news, you help make a small part of it happen.",
    "climate_link": "Read how Stripe Climate works",
    "editorial_independence_title": "Editorial Independence",
    "editorial_independence_text": "Our AI summaries are created entirely independently of the source media, editorially. No news source whose content we summarize pays us or influences which stories we select or how we rewrite them. We link to the original article every time, so you can always verify and read further.",
    "pricing_title": "Choose your dose of sunshine ☀️",
