    "terms_title": "Our Agreements ✨",
    "terms_subtitle": "Clarity and positivity in everything we do.",
    "terms_sec1_title": "1. Our Mission",
    "terms_sec1_text": "BrightNews brings exclusively positive news. Our AI engine scans global sources to provide you with a fresh dose of optimism several times a day. By using our site, you agree to these terms.",
    "terms_sec2_title": "2. Use of Content",
    "terms_sec2_text": "Everything you read on BrightNews is intended for personal use. Commercially distributing our articles or data without written permission from Maarten de Klerk is not permitted.",
    "terms_sec3_title": "3. Subscriptions (Premium)",
    "terms_sec3_list1": "<strong>Access:</strong> Premium articles are exclusive to members with an active subscription.",
    "terms_sec3_list2": "<strong>Payment:</strong> You pay in advance for the chosen period.",
    "terms_sec3_list4": "<strong>Automatic renewal:</strong> Your subscription renews automatically for the chosen period (month or year), including after a free trial, until you cancel. Purchase confirmations and invoices are sent by Stripe.",
    "terms_sec3_list3": "<strong>Cancellation:</strong> You can stop your subscription at any time via your profile page. Access remains until the end of the billing period.",
    "terms_sec4_title": "4. The 'Bright' AI-Guarantee",
    "terms_sec4_text": "Our AI does its best to select only the most positive stories. Although we strive for 100% accuracy and positivity, the content is AI-generated and can sometimes contain interpretational errors. BrightNews is not liable for consequences of information in the articles.",
    "terms_sec5_title": "5. Changes",
    "terms_sec5_text": "The world changes, and so does BrightNews. We may adjust these terms occasionally to make them even clearer. The latest version is always here.",
    "refunds_title": "Refunds ✨",
    "refunds_subtitle": "Not satisfied? You get your money back.",
    "refunds_sec1_title": "1. 14-Day Money-Back Guarantee",
    "refunds_sec1_text": "Within 14 days of purchasing a Glow or Shine subscription, you can request a full refund — regardless of how many articles you've already read. This is a voluntary guarantee from BrightNews, not a legally required right (see point 2 below).",
    "refunds_sec2_title": "2. Relationship to Your Right of Withdrawal",
    "refunds_sec2_text": "Because you get immediate access to premium content when you subscribe, you explicitly request immediate delivery at checkout and thereby waive the statutory 14-day right of withdrawal that normally applies to digital services. This means we are not legally required to offer refunds. We offer this guarantee anyway, as a courtesy — you only truly pay once you're satisfied.",
    "refunds_sec3_title": "3. How to Request a Refund",
    "refunds_sec3_text": "Email info@brightnews.online with your account email address and the purchase date. We process requests within a few business days and refund via Stripe, using the same method as your original payment.",
    "refunds_sec4_title": "4. After the First 14 Days",
    "refunds_sec4_text": "After this period, you can cancel your subscription at any time via your profile page. Access remains active until the end of the current billing period, but no refund is given for that remaining period. See our Terms of Service for full cancellation terms.",
    "colofon_title": "Who are we? (Imprint)",
