    "v5_bd_titel_gelukt": "Willkommen bei Premium",
    "v5_bd_lead_gelukt": "Dein Probezeitraum hat begonnen und läuft bis {datum}. Bis dahin zahlst du nichts.",
    "v5_bd_abonnement": "Dein Abo",
    "v5_bd_plan": "Plan",
    "v5_bd_per_jaar": "pro Jahr",
    "v5_bd_per_maand": "pro Monat",
    "v5_bd_bedrag_jaar": "24,95 €",
