    "v5_bd_eerste_betaling": "Erste Zahlung",
    "v5_bd_bedrag_op": "{bedrag} am {datum}",
    "v5_bd_bevestiging": "Bestätigung",
    "v5_bd_gestuurd_naar": "Gesendet an {email}",
    "v5_bd_lees_vandaag": "Die Nachrichten von heute lesen",
    "v5_bd_verder_lezen": "Weiterlesen",
    "v5_bd_account_regel": "Kündigen oder den Plan ändern kannst du in {account}.",
    "v5_bd_titel_bezig": "Danke für deine Anmeldung",
    "v5_bd_lead_bezig": "Dein Probezeitraum hat begonnen: Heute zahlst du 0 €. Die erste Zahlung von {bedrag} ist am {datum}. Wir schalten Premium jetzt für {email} frei. Das dauert meist nur ein paar Sekunden.",
    "v5_bd_niets_doen": "Du musst nichts tun",
    "v5_bd_niets_doen_tekst": "Diese Seite aktualisiert sich von selbst, sobald Premium bereit ist. Du kannst sie auch einfach schließen: Dein Premium findest du danach in Mein Konto.",
    "v5_bd_lead_traag": "Deine Anmeldung hat geklappt, aber Premium ist noch nicht aktiv. Das dauert länger als sonst.",
    "v5_bd_traag_titel": "Melde dich nicht erneut an",
    "v5_bd_traag_tekst": "Aktualisiere die Seite in einer Minute. Klappt es dann noch nicht, sag uns Bescheid. Du zahlst nichts doppelt: Dein Probezeitraum von 30 Tagen beginnt erst, wenn Premium aktiv ist, und die erste Zahlung folgt erst danach.",
    "v5_bd_verversen": "Seite aktualisieren",
    "v5_bd_status_klaar": "Premium ist aktiv.",
    "v5_bd_status_traag": "Premium ist noch nicht aktiv. Das dauert länger als sonst.",
    "v5_oo_h1": "Gute Nachrichten, ohne Rauschen",
    "v5_oo_lead": "BrightNews sammelt jeden Tag Nachrichten darüber, was in der Welt gut läuft. Aus verlässlichen Quellen, kurz zusammengefasst, in fünf Sprachen.",
    "v5_oo_waarom_h2": "Warum BrightNews",
    "v5_oo_waarom_p1": "Die meisten Nachrichten handeln davon, was schiefgeht. Das ist wichtig, aber nicht die ganze Geschichte. Jeden Tag löst auch jemand ein Problem: eine neue Behandlung, ein saubererer Fluss, eine Erfindung, die Energie spart.",
    "v5_oo_waarom_p2": "BrightNews zeigt diese Seite. Nicht, um die Probleme kleinzureden, sondern damit du nach dem Lesen weißt, was tatsächlich vorangeht.",
    "v5_oo_werkt_h2": "So funktioniert es",
    "v5_oo_werkt_intro": "BrightNews hat keine Redaktion. Drei Schritte, jeden Tag aufs Neue.",
    "v5_oo_stap1_t": "1. Sammeln",
    "v5_oo_stap1_p": "Wir holen Nachrichten aus verlässlichen Quellen, in fünf Sprachen.",
    "v5_oo_stap2_t": "2. Auswählen",
    "v5_oo_stap2_p": "KI gibt jeder Meldung eine Punktzahl. Nur Nachrichten, die wirklich etwas bringen, kommen auf die Seite.",
    "v5_oo_stap3_t": "3. Zusammenfassen",
    "v5_oo_stap3_p": "Jede Geschichte bekommt eine kurze Zusammenfassung, mit einem Link zur ursprünglichen Quelle.",
    "v5_oo_ai_h2": "Ehrlich über KI",
    "v5_oo_ai_p1": "Auswählen und Zusammenfassen übernimmt Claude, ein KI-Modell von Anthropic. Das klappt meistens gut, aber nicht immer. Deshalb steht bei jeder Geschichte die Quelle, damit du das Original lesen kannst.",
    "v5_oo_ai_fout": "Siehst du einen Fehler in einer Zusammenfassung? {link}.",
    "v5_oo_ai_link": "Sag uns Bescheid",
    "v5_oo_talen_h2": "Sechs Themen, fünf Sprachen",
    "v5_oo_talen_intro": "Nederlands, English, Deutsch, Français und Español. Wähle deine Sprache über Einstellungen oben auf der Seite.",
    "v5_oo_onderwerpen": "Themen",
    "v5_oo_betaald_h2": "Wie BrightNews finanziert wird",
    "v5_oo_betaald_p1": "Alle Zusammenfassungen sind kostenlos, für alle. Mit einem kostenlosen Konto liest du 5 vollständige Artikel pro Monat. Premium kostet 2,95 € pro Monat und bezahlt die Server und die KI. So bleibt BrightNews unabhängig.",
    "v5_oo_vragen_h2": "Fragen oder Ideen?",
    "v5_oo_vragen_intro": "Wir lesen alles, was du schickst.",
    "v5_zk_h1": "Wie eine Meldung auf BrightNews kommt",
    "v5_zk_lead": "BrightNews hat keine Redaktion. Ein festes Verfahren bestimmt, was du siehst. Hier steht dieses Verfahren, Schritt für Schritt.",
    "v5_zk_bron_h2": "Von der Quelle zur Zusammenfassung",
    "v5_zk_stap1_t": "Abrufen",
    "v5_zk_stap1_p": "Ein automatisches Programm holt jeden Tag neue Meldungen aus verlässlichen Nachrichtenquellen.",
    "v5_zk_stap2_t": "Bewerten",
    "v5_zk_stap2_p": "Claude, ein KI-Modell von Anthropic, liest jede Meldung und vergibt Punkte für drei Kriterien: gutes Gefühl (0 bis 3), positive Formulierung (0 bis 3) und Relevanz (0 bis 4). Zusammen ergibt das eine Punktzahl von 0 bis 10.",
    "v5_zk_stap3_t": "Auswählen",
    "v5_zk_stap3_p": "Auf die Seite kommt nur eine Meldung mit 8 oder mehr Punkten und mindestens 2 Punkten bei jedem Kriterium. An einem ruhigen Tag sind es weniger; wir füllen nicht mit weniger guten Nachrichten auf.",
    "v5_zk_stap4_t": "Zusammenfassen und einordnen",
    "v5_zk_stap4_p": "Claude schreibt eine kurze Zusammenfassung in fünf Sprachen und wählt eines der sechs Themen: Tech, Gesundheit, Wissenschaft, Lifestyle, Umwelt oder Finanzen.",
    "v5_zk_stap5_t": "Foto prüfen",
    "v5_zk_stap5_p": "Ist das Foto schmaler als 800 Pixel, ein Logo oder eine einfarbige Fläche? Dann zeigen wir kein Foto, sondern unser eigenes Bild.",
    "v5_zk_stap6_t": "Tagesüberblick erstellen",
    "v5_zk_stap6_p": "Einmal am Tag bündeln wir die wichtigsten Geschichten in einem Tagesüberblick, mit allen Quellen. Ein Tag geht von 00:00 bis 24:00 Uhr niederländischer Zeit.",
    "v5_zk_letten_h2": "Worauf wir achten",
    "v5_zk_letten_intro": "Gute Nachrichten heißt nicht: nur nette Meldungen. Jede Meldung bekommt Punkte für drei Kriterien, zusammen 0 bis 10. Ab 8 kommt sie auf die Seite, wenn jedes Kriterium mindestens 2 erreicht.",
    "v5_zk_punten_h3": "So vergeben wir Punkte",
    "v5_zk_punt1": "Gutes Gefühl, 0 bis 3: Macht dich der Kern der Geschichte froh, hoffnungsvoll oder warm ums Herz?",
    "v5_zk_punt2": "Positive Formulierung, 0 bis 3: Erzählt die Meldung selbst, was gut läuft, ohne Krisensprache?",
    "v5_zk_punt3": "Relevanz, 0 bis 4: Bedeutet es etwas für die Gesellschaft, oder erkennst du dich oder deine Umgebung darin wieder?",
    "v5_zk_liggen_h3": "Das lassen wir weg",
    "v5_zk_liggen1": "Krieg, Gewalt, Kriminalität oder Katastrophen als Kern der Geschichte",
    "v5_zk_liggen2": "Werbung, Produktnachrichten, Rezensionen und Börsennachrichten",
    "v5_zk_liggen3": "Politik, Klatsch, Listen und Clickbait",
    "v5_zk_elk_h2": "Was du bei jeder Geschichte siehst",
    "v5_zk_elk_intro": "So kannst du selbst prüfen, woher sie kommt.",
    "v5_zk_elk1": "Die Quelle, mit einem Link zum ursprünglichen Artikel",
    "v5_zk_elk2": "Das Thema",
    "v5_zk_elk3": "Wann wir die Geschichte verarbeitet haben, in deiner Zeitzone",
    "v5_zk_elk4": "Eine Zusammenfassung; mit Premium oder Guthaben auch der vollständige Artikel",
    "v5_zk_grenzen_h2": "Was KI nicht immer richtig macht",
    "v5_zk_grenzen_p1": "KI kann eine Nuance übersehen oder eine Zahl falsch übernehmen. Niemand liest jede Geschichte vorab. Deshalb steht die Quelle immer dabei, und du kannst einen Fehler melden. Meldungen lesen wir sehr wohl, und Fehler korrigieren wir.",
    "v5_zk_fout": "Fehler entdeckt? {link}.",
    "v5_zk_meld": "Melde ihn über Feedback",
    "v5_zk_vragen": "Fragen",
    "v5_zk_faq1_v": "Warum sehe ich manchmal nur wenige Geschichten?",
    "v5_zk_faq1_a": "An ruhigen Tagen erreichen weniger Meldungen eine hohe Punktzahl. Wir füllen dann nicht mit weniger guten Nachrichten auf.",
    "v5_zk_faq2_v": "Kann ich eine Geschichte oder Quelle vorschlagen?",
    "v5_zk_faq2_a": "Ja, schick sie über Kontakt. Eine vorgeschlagene Geschichte durchläuft dieselbe Bewertung wie jede andere Meldung, daher können wir nicht versprechen, dass sie auf die Seite kommt.",
    "v5_zk_faq3_v": "Bezahlt jemand dafür, auf BrightNews zu erscheinen?",
    "v5_zk_faq3_a": "Nein. Auf BrightNews gibt es keine Werbung, und niemand kann für einen Platz bezahlen. Die Bewertung ist für jede Meldung gleich.",
    "v5_ct_lead": "Eine Frage, eine Idee oder etwas, das nicht stimmt? Schick uns eine Nachricht. Wir lesen alles.",
