    "colofon_link_odr": "EU-OS-Plattform",
    "privacy_text_intro": "Bei BrightNews konzentrieren wir uns auf das Positive. Das gilt auch für Ihre Daten. Wir verarbeiten nur das, was für unseren Service unbedingt erforderlich ist.",
    "privacy_list_subscription": "<strong>Abonnements:</strong> Für 'Glow'- und 'Shine'-Mitglieder verarbeiten wir Zahlungen über Stripe, unseren Merchant of Record. Wir speichern keine Kreditkartennummern auf unseren eigenen Servern.",
    "privacy_list_account": "<strong>Kontodaten:</strong> Wir nutzen Supabase (gehostet in der EU) zur Verarbeitung deiner E-Mail-Adresse und Kontoeinstellungen für Login und Kontoverwaltung.",
    "privacy_list_hosting": "<strong>Datenspeicherung:</strong> Ihre Kontodaten und Premium-Artikel werden bei Supabase gespeichert, auf Servern innerhalb der EU und unter einem Auftragsverarbeitungsvertrag (AVV). Die Website selbst wird über GitHub Pages gehostet.",
    "privacy_list_newsletter": "<strong>Newsletter-Anmeldung:</strong> Wenn du dich über unsere Launch-Seite für Updates anmeldest, wird deine E-Mail-Adresse ausschließlich für diese Anmeldung von Formspree verarbeitet.",
    "cookies_title": "Cookies & Technologie",
    "cookies_text": "BrightNews verwendet funktionale Cookies und lokalen Speicher, um Ihre Spracheinstellungen und Sitzungen zu speichern. Wir nutzen datenschutzfreundliche Analysen. Für Tracking über die funktionale Notwendigkeit hinaus fragen wir Sie stets um Erlaubnis.",
    "transparency_title": "KI & Barrierefreiheit",
    "transparency_text": "Unsere Nachrichten werden durch KI generiert. Wir glauben an Transparenz: Jeder Artikel enthält einen KI-Hinweis. Zudem bekennen wir uns zu den <strong>WCAG 2.1 AA</strong>-Standards für Barrierefreiheit.",
    "renewal_notice": "Nach der Gratis-Probephase € 2,95/Monat; verlängert sich automatisch, jederzeit kündbar.",
    "renewal_notice_year": "Nach der Gratis-Probephase € 24,95/Jahr; verlängert sich automatisch, jederzeit kündbar.",
    "feat_14days": "✅ Sofortiger Zugriff",
