    "portal_url_missing": "Kein Verwaltungslink gefunden. Bitte kontaktiere uns über die Kontaktseite, um dein Abonnement zu kündigen.",
    "privacy_list_withdrawal": "<strong>Widerrufsrecht:</strong> Mit Beginn des Abonnements stimmen Sie der sofortigen Ausführung zu und verzichten auf das Widerrufsrecht.",
    "colofon_val_odr": "EU ODR-Plattform",
    "privacy_list_payments": "<strong>Zahlungen:</strong> Zahlungen werden sicher über Stripe, unseren Merchant of Record, abgewickelt. Wir speichern keine Kreditkartendaten.",
    "cookies_text2": "BrightNews verwendet funktionale Cookies und lokalen Speicher, um deine Einstellungen wie Sprache und Login-Sitzung sicher zu speichern. Für Analyse- oder Tracking-Cookies bitten wir dich immer zuerst über den Banner um Erlaubnis. So behältst du die volle Kontrolle über deine Daten.",
