    "btn_upgrade_now": "Jetzt upgraden",
    "btn_login_to_read": "Anmelden zum Weiterlesen",
    "share_article": "Nachricht teilen",
    "share_label": "Teilen",
    "copy_success": "Link kopiert!",
    "about_badge": "Hallo Sonnenschein! ☀️",
    "about_hero_title": "Wir sind deine tägliche Dosis gute Nachrichten.",
    "about_hero_p": "Seien wir ehrlich: Die Welt kann manchmal etwas überwältigend sein. Bei BrightNews setzen wir die Sonnenbrille auf und konzentrieren uns auf die schönen Dinge, die Tatsächlich passieren.",
    "about_why_title": "Warum BrightNews?",
    "about_why_p": "Weil wir glauben, dass eine positive Einstellung ansteckend ist! Von Wissenschaftlern, die Ozeane reinigen, bis hin zu kleinen Taten der Freundlichkeit an der Straßenecke; es gibt so viel Grund zur Freude. Wir filtern den Lärm heraus und zeigen die Lichtblicke.",
    "about_feat1_title": "Keine Wolken",
    "about_feat1_p": "Nur Nachrichten, die dir Energie geben und die du mit gutem Gewissen teilen kannst.",
    "about_feat2_title": "Weltweit",
    "about_feat2_p": "Gute Dinge passieren überall, von Amsterdam bis ans andere Ende der Welt.",
    "about_feat3_title": "Pünktlich um 12:00",
    "about_feat3_p": "Pünktlich zum Mittagessen servieren wir dir deine tägliche Dosis gute Nachrichten. Täglich frisch um 12:00 und 00:00 UTC (12 PM und 12 AM).",
    "about_how_title": "Wie zaubern wir das auf deinen Bildschirm?",
    "about_how_p": "Keine komplizierten Handbücher, sondern ein smarter Computer (unsere KI), der glückliche Geschichten liebt. Das passiert jeden Tag:",
    "about_step1": "<strong>Schritt 1: Suchen 🔍</strong> - Unser Computer liest Tausende von Zeitungen und Blogs weltweit.",
    "about_step2": "<strong>Schritt 2: Lächeln-Check 😊</strong> - Ist die Nachricht hoffnungsvoll? Macht sie uns glücklich? Wenn ja, darf sie durch!",
    "about_step3": "<strong>Schritt 3: Übersetzen 🗣️</strong> - Wir machen daraus eine schöne Kurzgeschichte in deiner Sprache.",
    "about_step4": "<strong>Tadaa! 🎉</strong> - Um Punkt 12:00 Uhr steht sie auf der Website für dich bereit.",
    "climate_title": "Gemeinsam mit Stripe holen wir CO₂ aus der Luft",
    "climate_text": "Ein fester Anteil jedes Abonnements fließt über Stripe Climate in die dauerhafte Entnahme von CO₂ aus der Atmosphäre. Stripe bündelt diese Beiträge und kauft damit Kohlenstoffentnahme bei Unternehmen ein, die diese Technologie gerade erst aufbauen — Arbeit, die heute noch viel zu teuer ist, um von allein zu entstehen. Bei uns liest du also nicht nur gute Klimanachrichten, du ermöglichst auch ein kleines Stück davon.",
    "climate_link": "So funktioniert Stripe Climate",
    "editorial_independence_title": "Redaktionelle Unabhängigkeit",
    "editorial_independence_text": "Unsere KI-Zusammenfassungen entstehen redaktionell vollständig unabhängig von den Quellmedien. Keine Nachrichtenquelle, deren Inhalte wir zusammenfassen, bezahlt uns oder beeinflusst, welche Geschichten wir auswählen oder wie wir sie umschreiben. Wir verlinken bei jedem Artikel auf das Original, damit du selbst überprüfen und weiterlesen kannst.",
    "pricing_title": "Wähle deine Dosis Sonnenschein ☀️",
