    "terms_title": "Unsere Vereinbarungen ✨",
    "terms_subtitle": "Klarheit und Positivität in allem, was wir tun.",
    "terms_sec1_title": "1. Unsere Mission",
    "terms_sec1_text": "BrightNews bringt ausschließlich positive Nachrichten. Unsere KI-Engine scannt weltweite Quellen, um dich mehrmals täglich mit einer frischen Dosis Optimismus zu versorgen. Durch die Nutzung unserer Website erklärst du dich mit diesen Bedingungen einverstanden.",
    "terms_sec2_title": "2. Nutzung der Inhalte",
    "terms_sec2_text": "Alles, was du auf BrightNews liest, ist für den persönlichen Gebrauch bestimmt. Es ist nicht gestattet, unsere Artikel oder Daten ohne schriftliche Genehmigung von Maarten de Klerk kommerziell te verbreiten.",
    "terms_sec3_title": "3. Abonnements (Premium)",
    "terms_sec3_list1": "<strong>Zugang:</strong> Premium-Artikel sind exklusiv für Mitglieder mit einem aktiven Abonnement.",
    "terms_sec3_list2": "<strong>Zahlung:</strong> Du zahlst im Voraus für den gewählten Zeitraum.",
    "terms_sec3_list4": "<strong>Automatische Verlängerung:</strong> Dein Abonnement verlängert sich automatisch um den gewählten Zeitraum (Monat oder Jahr), auch nach einer kostenlosen Probephase, bis du kündigst. Kaufbestätigungen und Rechnungen erhältst du von Stripe.",
    "terms_sec3_list3": "<strong>Kündigung:</strong> Du kannst dein Abonnement jederzeit über deine Profilseite beenden. Der Zugang bleibt bis zum Ende des Abrechnungszeitraums bestehen.",
    "terms_sec4_title": "4. Die 'Bright' KI-Garantie",
    "terms_sec4_text": "Unsere KI gibt ihr Bestes, um nur die positivsten Geschichten auszuwählen. Obwohl wir nach 100% Genauigkeit und Positivität streben, werden die Inhalte von KI generiert und können manchmal Interpretationsfehler enthalten. BrightNews haftet nicht für die Folgen von Informationen in den Artikeln.",
    "terms_sec5_title": "5. Änderungen",
    "terms_sec5_text": "Die Welt ändert sich, und so auch BrightNews. Wir können diese Bedingungen gelegentlich anpassen, um sie noch klarer te gestalten. Die neueste Version steht immer hier.",
    "refunds_title": "Rückerstattungen ✨",
    "refunds_subtitle": "Nicht zufrieden? Du bekommst dein Geld zurück.",
    "refunds_sec1_title": "1. 14 Tage Geld-zurück-Garantie",
    "refunds_sec1_text": "Innerhalb von 14 Tagen nach dem Kauf eines Glow- oder Shine-Abonnements kannst du auf Anfrage eine vollständige Rückerstattung erhalten — unabhängig davon, wie viele Artikel du bereits gelesen hast. Dies ist eine freiwillige Garantie von BrightNews, kein gesetzlich vorgeschriebenes Recht (siehe Punkt 2).",
    "refunds_sec2_title": "2. Verhältnis zu deinem Widerrufsrecht",
    "refunds_sec2_text": "Da du beim Abschluss eines Abonnements sofortigen Zugriff auf Premium-Inhalte erhältst, verlangst du beim Bezahlvorgang ausdrücklich die sofortige Lieferung und verzichtest damit auf das gesetzliche 14-tägige Widerrufsrecht, das normalerweise für digitale Dienstleistungen gilt. Das bedeutet, dass wir gesetzlich nicht zur Rückerstattung verpflichtet sind. Wir bieten diese Garantie trotzdem an, aus Kulanz — du zahlst wirklich erst, wenn du zufrieden bist.",
    "refunds_sec3_title": "3. Wie beantragst du eine Rückerstattung?",
    "refunds_sec3_text": "Sende eine E-Mail an info@brightnews.online mit der E-Mail-Adresse deines Kontos und dem Kaufdatum. Wir bearbeiten deine Anfrage innerhalb weniger Werktage und erstatten über Stripe, auf demselben Weg wie deine ursprüngliche Zahlung.",
    "refunds_sec4_title": "4. Nach den ersten 14 Tagen",
    "refunds_sec4_text": "Nach diesem Zeitraum kannst du dein Abonnement jederzeit über deine Profilseite kündigen. Dein Zugang bleibt bis zum Ende des laufenden Abrechnungszeitraums aktiv, es erfolgt jedoch keine Rückerstattung für diesen verbleibenden Zeitraum. Die vollständigen Kündigungsbedingungen findest du in unseren AGB.",
