    "privacy_text_intro": "Chez BrightNews, nous nous concentrons sur le positif. Cela s'applique aussi à vos données. Nous ne traitons que ce qui est strictement nécessaire à notre service.",
    "privacy_list_subscription": "<strong>Abonnements :</strong> Pour les membres 'Glow' et 'Shine', nous traitons les paiements via Stripe, notre Merchant of Record. Nous ne stockons pas de numéros de carte de crédit sur nos serveurs.",
    "privacy_list_account": "<strong>Données de compte :</strong> Nous utilisons Supabase (hébergé dans l'UE) pour traiter votre adresse e-mail et vos paramètres de compte pour la connexion et la gestion du compte.",
    "privacy_list_hosting": "<strong>Stockage des données :</strong> Vos données de compte et les articles premium sont stockés chez Supabase, sur des serveurs situés dans l'UE et couverts par un accord de traitement des données (DPA). Le site lui-même est hébergé via GitHub Pages.",
    "privacy_list_newsletter": "<strong>Inscription à la newsletter :</strong> Si vous vous inscrivez pour recevoir des mises à jour via notre page de lancement, votre adresse e-mail est traitée par Formspree uniquement pour recevoir votre inscription.",
    "cookies_title": "Cookies et technologie",
    "cookies_text": "BrightNews utilise des cookies fonctionnels et le stockage local pour mémoriser vos préférences linguistiques. Nous utilisons des analyses respectueuses de la vie privée. Pour tout suivi non fonctionnel, nous demanderons toujours votre autorisation.",
