    "about_badge": "Bonjour rayon de soleil ! ☀️",
    "about_hero_title": "Nous sommes votre dose quotidienne de bonnes nouvelles.",
    "about_hero_p": "Soyons honnêtes : le monde peut parfois être un peu accablant. Chez BrightNews, nous mettons nos lunettes de soleil et nous nous concentrons sur les belles choses qui se produisent RÉELLEMENT.",
    "about_why_title": "Pourquoi BrightNews ?",
    "about_why_p": "Parce que nous croyons qu'une vision positive est contagieuse ! Des scientifiques qui nettoient les océans aux petits actes de gentillesse au coin de la rue ; il y a tant de raisons d'être joyeux. Nous filtrons le bruit pour ne montrer que les lueurs d'espoir.",
    "about_feat1_title": "Pas de Nuages",
    "about_feat1_p": "Uniquement des histoires qui vous donnent de l'énergie et que vous pouvez partager en toute confiance.",
    "about_feat2_title": "Mondial",
    "about_feat2_p": "De bonnes choses arrivent partout, d'Amsterdam à l'autre bout de l'océan.",
    "about_feat3_title": "Précis à 12:00",
    "about_feat3_p": "Juste à l'heure pour le déjeuner, nous servons votre dose quotidienne de bonnes nouvelles. Frais tous les jours à 12:00 et 00:00 UTC (12 PM et 12 AM).",
    "about_how_title": "Comment cela arrive-t-il sur votre écran ?",
    "about_how_p": "Pas de manuels compliqués, juste un ordinateur intelligent (notre IA) qui adore les histoires joyeuses. Voici ce qui se passe chaque jour :",
    "about_step1": "<strong>Étape 1 : Recherche 🔍</strong> - Notre ordinateur lit des milliers de journaux et de blogs dans le monde entier.",
    "about_step2": "<strong>Étape 2 : Check Sourire 😊</strong> - Le message est-il porteur d'espoir ? Nous rend-il heureux ? Si oui, il est validé !",
    "about_step3": "<strong>Étape 3 : Traduction 🗣️</strong> - Nous en faisons une courte histoire sympa dans votre propre langue.",
    "about_step4": "<strong>Tadaa ! 🎉</strong> - À midi pile, c'est prêt pour vous sur le site.",
    "climate_title": "Avec Stripe, nous retirons du CO₂ de l’atmosphère",
    "climate_text": "Une part fixe de chaque abonnement est versée via Stripe Climate au retrait permanent de CO₂ de l’atmosphère. Stripe regroupe ces contributions et achète de l’élimination de carbone auprès d’entreprises qui construisent encore cette technologie — un travail bien trop coûteux aujourd’hui pour voir le jour tout seul. Chez nous, vous ne lisez donc pas seulement de bonnes nouvelles pour le climat : vous en rendez une petite partie possible.",
    "climate_link": "Découvrez comment fonctionne Stripe Climate",
    "editorial_independence_title": "Indépendance Éditoriale",
    "editorial_independence_text": "Nos résumés générés par IA sont créés en toute indépendance éditoriale vis-à-vis des médias sources. Aucune source d'actualité dont nous résumons le contenu ne nous paie ni n'influence les histoires que nous sélectionnons ou la façon dont nous les réécrivons. Nous renvoyons systématiquement vers l'article original, afin que vous puissiez vérifier et en savoir plus.",
    "pricing_title": "Choisissez votre dose de soleil ☀️",
