    "terms_title": "Nos Engagements ✨",
    "terms_subtitle": "Clarté et positivité dans tout ce que nous faisons.",
    "terms_sec1_title": "1. Notre Mission",
    "terms_sec1_text": "BrightNews apporte exclusivement des nouvelles positives. Notre moteur d'IA scanne des sources mondiales pour vous offrir plusieurs fois par jour une dose d'optimisme. En utilisant notre site, vous acceptez ces conditions.",
    "terms_sec2_title": "2. Utilisation du Contenu",
    "terms_sec2_text": "Tout ce que vous lisez sur BrightNews est destiné à un usage personnel. La distribution commerciale de nos articles ou données sans l'autorisation écrite de Maarten de Klerk n'est pas autorisée.",
    "terms_sec3_title": "3. Abonnements (Premium)",
    "terms_sec3_list1": "<strong>Accès :</strong> Les articles Premium sont exclusifs aux membres ayant un abonnement actif.",
    "terms_sec3_list2": "<strong>Paiement :</strong> Vous payez d'avance pour la période choisie.",
    "terms_sec3_list4": "<strong>Renouvellement automatique :</strong> Votre abonnement se renouvelle automatiquement pour la période choisie (mois ou an), y compris après une période d'essai gratuite, jusqu'à résiliation. Les confirmations d'achat et factures sont envoyées par Stripe.",
    "terms_sec3_list3": "<strong>Riliation :</strong> Vous pouvez arrêter votre abonnement à tout moment via votre page de profil. L'accès est maintenu jusqu'à la fin de la période de facturation.",
    "terms_sec4_title": "4. La Garantie IA 'Bright'",
    "terms_sec4_text": "Notre IA fait de son mieux pour ne sélectionner que les histoires les plus positives. Bien que nous visions 100% d'exactitude et de positivité, le contenu est généré par l'IA et peut parfois contenir des erreurs d'interprétation. BrightNews n'est pas responsable des conséquences des informations contenues dans les articles.",
    "terms_sec5_title": "5. Modifications",
    "terms_sec5_text": "Le monde change, et BrightNews aussi. Nous pouvons ajuster ces conditions de temps à autre pour les rendre encore plus claires. La version la plus récente sera toujours ici.",
    "refunds_title": "Remboursements ✨",
    "refunds_subtitle": "Pas satisfait ? Vous êtes remboursé.",
    "refunds_sec1_title": "1. Garantie de remboursement de 14 jours",
    "refunds_sec1_text": "Dans les 14 jours suivant l'achat d'un abonnement Glow ou Shine, vous pouvez demander un remboursement intégral — quel que soit le nombre d'articles déjà lus. Il s'agit d'une garantie volontaire de BrightNews, et non d'un droit légalement obligatoire (voir le point 2 ci-dessous).",
    "refunds_sec2_title": "2. Relation avec votre droit de rétractation",
    "refunds_sec2_text": "Comme vous obtenez un accès immédiat au contenu premium lors de votre abonnement, vous demandez explicitement une livraison immédiate lors du paiement et renoncez ainsi au droit de rétractation légal de 14 jours qui s'applique normalement aux services numériques. Cela signifie que nous ne sommes pas légalement tenus d'offrir des remboursements. Nous proposons tout de même cette garantie, par courtoisie — vous ne payez vraiment que si vous êtes satisfait.",
    "refunds_sec3_title": "3. Comment demander un remboursement ?",
    "refunds_sec3_text": "Envoyez un e-mail à info@brightnews.online avec l'adresse e-mail de votre compte et la date d'achat. Nous traitons les demandes sous quelques jours ouvrables et remboursons via Stripe, selon le même mode que votre paiement initial.",
    "refunds_sec4_title": "4. Après les 14 premiers jours",
    "refunds_sec4_text": "Après cette période, vous pouvez résilier votre abonnement à tout moment via votre page de profil. L'accès reste actif jusqu'à la fin de la période de facturation en cours, mais aucun remboursement n'est accordé pour cette période restante. Consultez nos Conditions Générales pour les modalités complètes de résiliation.",
    "contact_mail_header": "Envoyez-nous un e-mail",
    "contact_mail_text": "Vous avez une question ou vous voulez juste dire bonjour ? Vous kunt nous joindre à tout moment à :",
    "contact_feedback_header": "Améliorations et Idées",
    "contact_feedback_text": "Avez-vous des suggestions pour rendre le site encore meilleur ? Ou des commentaires généraux ? Nous serions ravis de les entendre ! N'hésitez pas à partager vos pensées avec nous par e-mail.",
    "contact_social_header": "Réseaux Sociaux",
    "contact_social_text": "Nous gardons volontairement une présence minimale sur les réseaux sociaux pour rester concentrés sur la qualité. L'e-mail est le moyen le plus rapide de nous joindre.",
