    "v5_pv_s5_p": "[Completar plazos de conservación.] Si borras tu cuenta, eliminamos tus datos en un plazo de [completar plazo].",
    "v5_pv_s6": "Cookies",
    "v5_pv_s6_p": "Usamos el almacenamiento de tu navegador para iniciar sesión y recordar tus preferencias de idioma y visualización, no para seguirte. Si permites \"Estadísticas\" en la barra de cookies, Google Analytics (GA4) coloca cookies para contar visitas. Sin ese permiso no las colocamos. Puedes cambiar tu elección cuando quieras en la barra de cookies.",
    "v5_pv_s6_link": "Cambiar la configuración de cookies",
    "v5_pv_s7": "Tus derechos",
    "v5_pv_s7_p": "Puedes consultar tus datos, pedir que se corrijan o que se borren. Tu cuenta la borras tú mismo en Mi cuenta. Si no estás de acuerdo con cómo tratamos tus datos, puedes presentar una reclamación ante la autoridad neerlandesa de protección de datos (Autoriteit Persoonsgegevens).",
    "v5_av_kort1": "Los resúmenes son gratis. Con una cuenta gratuita lees 5 artículos completos al mes.",
    "v5_av_kort2": "Premium empieza con 30 días gratis y después se renueva cada mes o cada año, hasta que canceles en Mi cuenta.",
    "v5_av_kort3": "La IA elige y resume. Suele salir bien, pero no siempre; la fuente siempre aparece.",
    "v5_av_kort4": "Lo que lees en BrightNews es para uso personal.",
    "v5_av_s1": "Sobre estas condiciones",
    "v5_av_s1_p": "Estas condiciones se aplican a todas las personas que usan brightnews.online. BrightNews pertenece a BrightNews, Vossenstraat 19, 6286 BW Nijswiller, Países Bajos (registro mercantil 42048341, IVA NL005455019B94). Al usar la web, aceptas estas condiciones.",
    "v5_av_s2": "Qué hace BrightNews",
    "v5_av_s2_p": "BrightNews reúne noticias positivas de fuentes fiables. Claude, un modelo de IA de Anthropic, elige las historias y escribe los resúmenes. Puede colarse un error o un matiz perdido. Por eso cada historia muestra su fuente, para que puedas leer el original. BrightNews no se hace responsable de las consecuencias de la información de los resúmenes. [Revisar por un abogado.]",
    "v5_av_s3": "Tu cuenta",
    "v5_av_s3_p": "Una cuenta gratuita es para una sola persona. Con ella lees 5 artículos completos al mes; el saldo vuelve a empezar el día uno de cada mes. Guarda tus datos de acceso para ti. Tu cuenta la borras tú mismo en Mi cuenta.",
    "v5_av_s4": "Premium y pagos",
    "v5_av_s4_l1": "Prueba: Premium empieza con 30 días gratis. Si cancelas en ese tiempo, no pagas nada.",
    "v5_av_s4_l2": "Precio: 2,95 € al mes o 24,95 € al año. Pagas por adelantado el periodo elegido, a través de Stripe.",
    "v5_av_s4_l3": "Renovación: tu suscripción se renueva sola cada mes o cada año hasta que canceles. Los recibos te los envía Stripe.",
    "v5_av_s4_l4": "Cancelar: lo haces tú mismo, cuando quieras, en Mi cuenta. Mantienes Premium hasta el final del periodo que ya has pagado.",
    "v5_av_s4_p": "Cómo y cuándo recuperas tu dinero se explica en la política de reembolso.",
    "v5_av_s5": "Uso del contenido",
    "v5_av_s5_p": "Lo que lees en BrightNews es para uso personal. Compartir con los botones de una historia siempre está permitido. Distribuir artículos o datos con fines comerciales solo se permite con nuestro permiso por escrito. Los artículos originales siguen siendo de su fuente.",
    "v5_av_s6": "Cambios",
    "v5_av_s6_p": "Podemos cambiar estas condiciones. La versión más reciente siempre está en esta página, con la fecha arriba. Si cambia algo esencial para Premium, te avisamos antes. [Completar plazo.]",
    "v5_rf_kort1": "Los primeros 30 días son gratis. Si cancelas en ese tiempo, no pagas nada.",
    "v5_rf_kort2": "En los 14 días siguientes a tu primer pago, te devolvemos todo el dinero si lo pides.",
    "v5_rf_kort3": "Después puedes cancelar cuando quieras; mantienes Premium hasta el final del periodo, sin reembolso del resto.",
    "v5_rf_s1": "El periodo de prueba",
    "v5_rf_s1_p": "Premium empieza con 30 días gratis. Hoy pagas 0 €. Si cancelas en Mi cuenta dentro de esos 30 días, no se realiza ningún pago.",
    "v5_rf_s2": "14 días de devolución",
    "v5_rf_s2_p": "En los 14 días siguientes a tu primer pago por Glow o Shine te devolvemos todo el dinero si lo pides, da igual cuántos artículos hayas leído.",
    "v5_rf_s3": "Relación con tu derecho de desistimiento",
    "v5_rf_s3_p": "Al pagar pides acceso inmediato a Premium. Con ello renuncias al derecho legal de desistimiento de 14 días para servicios digitales. Por ley no estamos obligados a devolver el dinero; aun así te damos los 14 días de devolución, por iniciativa propia. [Revisar por un abogado.]",
    "v5_rf_s4": "Cómo pedirlo",
    "v5_rf_s4_p": "Envía un mensaje a través de Contacto y elige \"Pregunta sobre mi suscripción\". Indica el correo de tu cuenta y la fecha del pago. Devolvemos el dinero en pocos días laborables con Stripe, de la misma forma en que pagaste.",
    "v5_rf_s5": "Después de los primeros 14 días",
    "v5_rf_s5_p": "Después puedes cancelar cuando quieras en Mi cuenta. Mantienes Premium hasta el final del periodo que ya has pagado; ese periodo restante no se reembolsa.",
