    "v5_bd_titel_bezig": "Gracias por suscribirte",
    "v5_bd_lead_bezig": "Tu periodo de prueba ha empezado: hoy pagas 0 €. El primer pago, {bedrag}, será el {datum}. Ahora activamos Premium para {email}. Suele tardar unos segundos.",
    "v5_bd_niets_doen": "No tienes que hacer nada",
    "v5_bd_niets_doen_tekst": "Esta página se actualiza sola en cuanto Premium esté listo. También puedes cerrarla: después verás tu Premium en Mi cuenta.",
    "v5_bd_lead_traag": "Tu suscripción se ha completado, pero Premium aún no está activo. Está tardando más de lo normal.",
    "v5_bd_traag_titel": "No vuelvas a suscribirte",
    "v5_bd_traag_tekst": "Actualiza la página dentro de un minuto. Si sigue sin funcionar, avísanos. No pagas nada dos veces: tu prueba de 30 días solo empieza cuando Premium esté activo, y el primer pago llega después.",
    "v5_bd_verversen": "Actualizar la página",
    "v5_bd_status_klaar": "Premium está activo.",
    "v5_bd_status_traag": "Premium aún no está activo. Está tardando más de lo normal.",
    "v5_oo_h1": "Buenas noticias, sin ruido",
    "v5_oo_lead": "Cada día, BrightNews reúne noticias sobre lo que va bien en el mundo. De fuentes fiables, resumidas brevemente, en cinco idiomas.",
    "v5_oo_waarom_h2": "Por qué BrightNews",
    "v5_oo_waarom_p1": "La mayoría de las noticias hablan de lo que sale mal. Eso importa, pero no es toda la historia. Cada día alguien también resuelve un problema: un nuevo tratamiento, un río más limpio, un invento que ahorra energía.",
    "v5_oo_waarom_p2": "BrightNews muestra ese lado. No para quitarles importancia a los problemas, sino para que después de leer sepas qué sí avanza.",
    "v5_oo_werkt_h2": "Cómo funciona",
    "v5_oo_werkt_intro": "BrightNews no tiene redacción. Tres pasos, cada día de nuevo.",
    "v5_oo_stap1_t": "1. Recopilar",
    "v5_oo_stap1_p": "Recogemos noticias de fuentes fiables, en cinco idiomas.",
    "v5_oo_stap2_t": "2. Elegir",
    "v5_oo_stap2_p": "La IA da una puntuación a cada noticia. Solo las noticias que de verdad aportan algo llegan a la web.",
    "v5_oo_stap3_t": "3. Resumir",
    "v5_oo_stap3_p": "Cada historia recibe un breve resumen, con un enlace a la fuente original.",
    "v5_oo_ai_h2": "Sinceros sobre la IA",
    "v5_oo_ai_p1": "Elegir y resumir lo hace Claude, un modelo de IA de Anthropic. Suele salir bien, pero no siempre. Por eso cada historia muestra su fuente, para que puedas leer el original.",
    "v5_oo_ai_fout": "¿Ves un error en un resumen? {link}.",
    "v5_oo_ai_link": "Avísanos",
    "v5_oo_talen_h2": "Seis temas, cinco idiomas",
    "v5_oo_talen_intro": "Nederlands, English, Deutsch, Français y Español. Elige tu idioma en Ajustes, arriba en la página.",
    "v5_oo_onderwerpen": "Temas",
    "v5_oo_betaald_h2": "Cómo se financia BrightNews",
    "v5_oo_betaald_p1": "Todos los resúmenes son gratis, para todos. Con una cuenta gratuita lees 5 artículos completos al mes. Premium cuesta 2,95 € al mes y paga los servidores y la IA. Así BrightNews sigue siendo independiente.",
    "v5_oo_vragen_h2": "¿Preguntas o ideas?",
    "v5_oo_vragen_intro": "Leemos todo lo que nos envías.",
    "v5_zk_h1": "Cómo llega una noticia a BrightNews",
    "v5_zk_lead": "BrightNews no tiene redacción. Un método fijo decide lo que ves. Aquí está ese método, paso a paso.",
    "v5_zk_bron_h2": "De la fuente al resumen",
    "v5_zk_stap1_t": "Recoger",
    "v5_zk_stap1_p": "Un programa automático recoge cada día noticias nuevas de fuentes informativas fiables.",
    "v5_zk_stap2_t": "Valorar",
    "v5_zk_stap2_p": "Claude, un modelo de IA de Anthropic, lee cada noticia y da puntos según tres criterios: buena sensación (0 a 3), formulación positiva (0 a 3) y relevancia (0 a 4). Juntos dan una puntuación de 0 a 10.",
    "v5_zk_stap3_t": "Elegir",
    "v5_zk_stap3_p": "Solo llega a la web una noticia con una puntuación de 8 o más, y al menos 2 puntos en cada criterio. En un día tranquilo hay menos; no rellenamos con noticias menos buenas.",
    "v5_zk_stap4_t": "Resumir y clasificar",
    "v5_zk_stap4_p": "Claude escribe un breve resumen en cinco idiomas y elige uno de los seis temas: Tecnología, Salud, Ciencia, Estilo de vida, Medio ambiente o Finanzas.",
    "v5_zk_stap5_t": "Comprobar la foto",
    "v5_zk_stap5_p": "¿La foto mide menos de 800 píxeles de ancho, es un logotipo o un fondo liso? Entonces mostramos nuestra propia imagen.",
    "v5_zk_stap6_t": "Crear el resumen del día",
    "v5_zk_stap6_p": "Una vez al día reunimos las historias más importantes en un resumen del día, con todas las fuentes. Un día va de las 00:00 a las 24:00, hora de los Países Bajos.",
    "v5_zk_letten_h2": "En qué nos fijamos",
    "v5_zk_letten_intro": "Buenas noticias no significa: solo historias bonitas. Cada noticia recibe puntos según tres criterios, de 0 a 10 en total. A partir de 8 llega a la web, si cada criterio obtiene al menos 2.",
    "v5_zk_punten_h3": "Cómo damos los puntos",
    "v5_zk_punt1": "Buena sensación, 0 a 3: ¿el núcleo de la historia te alegra, te da esperanza o te emociona?",
    "v5_zk_punt2": "Formulación positiva, 0 a 3: ¿la noticia cuenta por sí misma lo que va bien, sin lenguaje de crisis?",
    "v5_zk_punt3": "Relevancia, 0 a 4: ¿significa algo para la sociedad, o te reconoces en ella a ti o a tu barrio?",
    "v5_zk_liggen_h3": "Lo que dejamos fuera",
    "v5_zk_liggen1": "Guerra, violencia, delincuencia o catástrofes como núcleo de la historia",
    "v5_zk_liggen2": "Publicidad, noticias de productos, reseñas y noticias bursátiles",
    "v5_zk_liggen3": "Política, cotilleos, listas y clickbait",
    "v5_zk_elk_h2": "Lo que ves en cada historia",
    "v5_zk_elk_intro": "Así puedes comprobar tú mismo de dónde viene.",
    "v5_zk_elk1": "La fuente, con un enlace al artículo original",
    "v5_zk_elk2": "El tema",
    "v5_zk_elk3": "Cuándo procesamos la historia, en tu zona horaria",
    "v5_zk_elk4": "Un resumen; con Premium o saldo, también el artículo completo",
    "v5_zk_grenzen_h2": "Lo que la IA no siempre hace bien",
    "v5_zk_grenzen_p1": "La IA puede pasar por alto un matiz o copiar mal una cifra. Nadie lee cada historia de antemano. Por eso la fuente siempre aparece, y puedes avisar de un error. Los avisos sí los leemos, y los errores los corregimos.",
    "v5_zk_fout": "¿Has visto un error? {link}.",
    "v5_zk_meld": "Avísanos en Comentarios",
    "v5_zk_vragen": "Preguntas",
    "v5_zk_faq1_v": "¿Por qué a veces solo veo unas pocas historias?",
    "v5_zk_faq1_a": "En los días tranquilos, menos noticias alcanzan una puntuación alta. No rellenamos con noticias menos buenas.",
    "v5_zk_faq2_v": "¿Puedo proponer una historia o una fuente?",
    "v5_zk_faq2_a": "Sí, envíala a través de Contacto. Una historia propuesta pasa por la misma valoración que cualquier otra noticia, así que no podemos prometer que aparezca en la web.",
    "v5_zk_faq3_v": "¿Alguien paga por aparecer en BrightNews?",
    "v5_zk_faq3_a": "No. En BrightNews no hay publicidad y nadie puede pagar por un sitio. La valoración es la misma para cada noticia.",
    "v5_ct_lead": "¿Una pregunta, una idea o algo que no está bien? Envíanos un mensaje. Lo leemos todo.",
