    "terms_sec6_title": "6. Reembolsos y Contacto",
    "terms_sec6_text": "¿Dudas sobre pagos? Escribe a info@BrightNews.online. Incluye el email de tu cuenta y los datos para el reembolso.",
    "colofon_val_address_full": "Vossenstraat 19, 6286BW Nijswiller, Países Bajos",
    "colofon_label_odr": "Resolución de litigios",
    "colofon_link_odr": "Plataforma ODR de la UE",
    "privacy_text_intro": "En BrightNews nos centramos en lo positivo. Eso también se aplica a tus datos. Solo procesamos lo estrictamente necesario para ofrecer nuestro servicio.",
    "privacy_list_subscription": "<strong>Suscripciones:</strong> Para los miembros 'Glow' y 'Shine', procesamos los pagos a través de Stripe, nuestro Merchant of Record. No almacenamos números de tarjeta en nuestros servidores.",
    "privacy_list_account": "<strong>Datos de la cuenta:</strong> Utilizamos Supabase (alojado en la UE) para procesar tu dirección de correo electrónico y la configuración de tu cuenta para el inicio de sesión y la gestión de la cuenta.",
    "privacy_list_hosting": "<strong>Almacenamiento:</strong> Tus datos de cuenta y los artículos premium se almacenan en Supabase, en servidores dentro de la UE y bajo un contrato de tratamiento de datos (DPA). El sitio web se aloja mediante GitHub Pages.",
    "privacy_list_newsletter": "<strong>Registro al boletín:</strong> Si te registras para recibir novedades a través de nuestra página de lanzamiento, tu dirección de correo electrónico es procesada por Formspree únicamente para recibir tu registro.",
    "cookies_title": "Cookies y Tecnología",
    "cookies_text": "BrightNews utiliza cookies funcionales y almacenamiento local para recordar tus preferencias. Usamos análisis respetuosos con la privacidad. Para cualquier seguimiento no esencial, siempre pediremos tu permiso primero.",
    "transparency_title": "IA y Accesibilidad",
    "transparency_text": "Nuestras noticias son generadas por IA. Creemos en la transparencia: cada artículo incluye un aviso de IA. Además, cumplimos con los estándares <strong>WCAG 2.1 AA</strong> para garantizar la accesibilidad.",
    "renewal_notice": "Tras la prueba gratuita 2,95 €/mes; se renueva automáticamente, cancela cuando quieras.",
    "renewal_notice_year": "Tras la prueba gratuita 24,95 €/año; se renueva automáticamente, cancela cuando quieras.",
    "feat_14days": "✅ Acceso inmediato",
    "feat_money": "✅ Sin cargos ocultos",
    "withdrawal_consent_label": "Acepto que el servicio comience de inmediato y, por lo tanto, renuncio a mi derecho de desistimiento legal de 14 días.",
    "withdrawal_consent_required": "Marca primero la casilla para continuar.",
    "portal_url_missing": "No se pudo encontrar un enlace de gestión. Contáctanos a través de la página de contacto para cancelar tu suscripción.",
    "privacy_list_withdrawal": "<strong>Derecho de desistimiento:</strong> Al iniciar la suscripción, acepta la entrega inmediata y renuncia al periodo de reflexión legal.",
    "colofon_val_odr": "Plataforma ODR de la UE",
    "privacy_list_payments": "<strong>Pagos:</strong> Las transacciones se procesan de forma segura a través de Stripe, nuestro Merchant of Record. No guardamos datos de tarjetas.",
    "cookies_text2": "BrightNews utiliza cookies funcionales y almacenamiento local para recordar tus preferencias, como el idioma y la sesión de inicio, de forma segura. Para las cookies analíticas o de seguimiento, siempre pedimos tu consentimiento a través del banner primero. De este modo, mantienes el control total sobre tus propios datos.",
