    "about_badge": "¡Hola, rayo de sol! ☀️",
    "about_hero_title": "Somos tu dosis diaria de buenas noticias.",
    "about_hero_p": "Seamos sinceros: el mundo puede ser un poco abrumador a veces. En BrightNews nos ponemos las gafas de sol y nos centramos en las cosas bonitas que SÍ están pasando.",
    "about_why_title": "¿Por qué BrightNews?",
    "about_why_p": "¡Porque creemos que el optimismo es contagioso! Desde científicos que limpian los océanos hasta pequeños actos de bondad en la esquina; hay mucho de qué alegrarse. Filtramos el ruido y mostramos los puntos de luz.",
    "about_feat1_title": "Sin Nubes",
    "about_feat1_p": "Solo historias que te dan energía y que puedes compartir con total confianza.",
    "about_feat2_title": "Mundial",
    "about_feat2_p": "Pasan cosas buenas en todas partes, desde Ámsterdam hasta el otro lado del océano.",
    "about_feat3_title": "Puntuales a las 12:00",
    "about_feat3_p": "Justo a tiempo para el almuerzo, servimos tu dosis diaria de buenas noticias. Frescas cada día a las 12:00 y 00:00 UTC (12 PM y 12 AM).",
    "about_how_title": "¿Cómo llevamos esto a tu pantalla?",
    "about_how_p": "Sin manuales complicados, solo un ordenador inteligente (nuestra IA) que ama las historias felices. Esto es lo que pasa cada día:",
    "about_step1": "<strong>Paso 1: Búsqueda 🔍</strong> - Nuestro ordenador lee miles de periódicos y blogs en todo el mundo.",
    "about_step2": "<strong>Paso 2: Filtro de Sonrisas 😊</strong> - ¿Es el mensaje esperanzador? ¿Nos hace felices? Si es así, ¡adelante!",
    "about_step3": "<strong>Paso 3: Traducción 🗣️</strong> - Lo convertimos en una historia corta y amena en tu propio idioma.",
    "about_step4": "<strong>¡Tachán! 🎉</strong> - A las 12:00 en punto, ya está listo para ti en la web.",
    "climate_title": "Junto a Stripe retiramos CO₂ del aire",
    "climate_text": "Una parte fija de cada suscripción se destina, a través de Stripe Climate, a retirar CO₂ de la atmósfera de forma permanente. Stripe reúne esas aportaciones y con ellas compra eliminación de carbono a empresas que aún están construyendo esa tecnología: un trabajo que hoy resulta demasiado caro para surgir por sí solo. Así que con nosotros no solo lees buenas noticias sobre el clima, también haces posible una pequeña parte de ellas.",
    "climate_link": "Descubre cómo funciona Stripe Climate",
    "editorial_independence_title": "Independencia Editorial",
    "editorial_independence_text": "Nuestros resúmenes generados por IA se elaboran de forma totalmente independiente, a nivel editorial, de los medios de origen. Ninguna fuente de noticias cuyo contenido resumimos nos paga ni influye en qué historias seleccionamos o cómo las reescribimos. Enlazamos siempre al artículo original, para que puedas verificarlo y seguir leyendo.",
    "pricing_title": "Elige tu dosis de sol ☀️",
