    "terms_title": "Nuestros Acuerdos ✨",
    "terms_subtitle": "Claridad y positividad en todo lo que hacemos.",
    "terms_sec1_title": "1. Nuestra Misión",
    "terms_sec1_text": "BrightNews ofrece exclusivamente noticias positivas. Nuestro motor de IA escanea fuentes mundiales para brindarte varias veces al día una dosis de optimismo. Al utilizar nuestro sitio, aceptas estos términos.",
    "terms_sec2_title": "2. Uso del Contenido",
    "terms_sec2_text": "Todo lo que lees en BrightNews está destinado a uso personal. No está permitida la distribución comercial de nuestros artículos o datos sin el permiso por escrito de Maarten de Klerk.",
    "terms_sec3_title": "3. Suscripciones (Premium)",
    "terms_sec3_list1": "<strong>Acceso:</strong> Los artículos Premium son exclusivos para miembros con una suscripción activa.",
    "terms_sec3_list2": "<strong>Pago:</strong> Pagas por adelantado por el periodo elegido.",
    "terms_sec3_list4": "<strong>Renovación automática:</strong> Tu suscripción se renueva automáticamente por el período elegido (mes o año), también tras una prueba gratuita, hasta que la canceles. Stripe envía las confirmaciones de compra y facturas.",
    "terms_sec3_list3": "<strong>Cancelación:</strong> Puedes cancelar tu suscripción en cualquier momento a través de tu página de perfil. El acceso se mantiene hasta el final del periodo de facturación.",
    "terms_sec4_title": "4. La Garantía de IA 'Bright'",
    "terms_sec4_text": "Nuestra IA hace todo lo posible para seleccionar solo las historias más positivas. Aunque buscamos un 100% de precisión y positividad, el contenido es generado por IA y a veces puede contener errores de interpretación. BrightNews no se hace responsable de las consecuencias de la información en los artículos.",
    "terms_sec5_title": "5. Cambios",
    "terms_sec5_text": "El mundo cambia, y BrightNews también. Podemos ajustar estos términos ocasionalmente para que sean aún más claros. La versión más reciente siempre estará aquí.",
    "refunds_title": "Reembolsos ✨",
    "refunds_subtitle": "¿No estás satisfecho? Te devolvemos tu dinero.",
    "refunds_sec1_title": "1. Garantía de devolución de 14 días",
    "refunds_sec1_text": "En los 14 días posteriores a la compra de una suscripción Glow o Shine, puedes solicitar un reembolso completo, independientemente de cuántos artículos hayas leído ya. Esta es una garantía voluntaria de BrightNews, no un derecho legalmente exigido (ver el punto 2 a continuación).",
    "refunds_sec2_title": "2. Relación con tu derecho de desistimiento",
    "refunds_sec2_text": "Como obtienes acceso inmediato al contenido premium al suscribirte, en el momento del pago solicitas expresamente la entrega inmediata y, por lo tanto, renuncias al derecho de desistimiento legal de 14 días que normalmente se aplica a los servicios digitales. Esto significa que no estamos legalmente obligados a ofrecer reembolsos. Aun así, ofrecemos esta garantía como cortesía: solo pagas de verdad cuando estás satisfecho.",
    "refunds_sec3_title": "3. ¿Cómo solicitar un reembolso?",
    "refunds_sec3_text": "Envía un correo a info@brightnews.online con la dirección de correo de tu cuenta y la fecha de compra. Procesamos las solicitudes en pocos días hábiles y reembolsamos a través de Stripe, mediante el mismo método que tu pago original.",
    "refunds_sec4_title": "4. Después de los primeros 14 días",
    "refunds_sec4_text": "Después de este periodo, puedes cancelar tu suscripción en cualquier momento desde tu página de perfil. El acceso permanece activo hasta el final del periodo de facturación en curso, pero no se realiza ningún reembolso por ese periodo restante. Consulta nuestros Términos y Condiciones para conocer las condiciones completas de cancelación.",
    "contact_mail_header": "Envíanos un correo electrónico",
    "contact_mail_text": "¿Tienes alguna pregunta o solo quieres saludar? Siempre puedes contactarnos en:",
    "contact_feedback_header": "Mejoras e Ideas",
    "contact_feedback_text": "¿Tienes sugerencias para mejorar aún más el sitio web? ¿O comentarios generales? ¡Nos encantaría escucharlos! No dudes en compartir tus pensamientos con nosotros por correo electrónico.",
    "contact_social_header": "Redes Sociales",
    "contact_social_text": "Mantenemos deliberadamente una presencia mínima en redes sociales para centrarnos en la calidad. El correo electrónico es la forma más rápida de contactarnos.",
    "colofon_title": "¿Quiénes somos? (Aviso Legal)",
